const std = @import("std");
const x86 = @import("root.zig");

pub const Family = enum(u5) {
    move = 0,
    extend = 1,
    address = 2,
    string = 3,
    arithmetic = 4,
    logic = 5,
    unary = 6,
    shift = 7,
    multiply = 8,
    divide = 9,
    condition = 10,
    control = 11,
    stack = 12,
    swap = 13,
    carry = 14,
    nop = 15,
    boundary = 16,
    system = 17,
    vector = 18,
    exchange = 19,
    interrupt = 20,
};

pub const Operation = enum(u8) {
    add = 0,
    and_ = 1,
    bswap = 2,
    call = 3,
    cmc = 4,
    cmovae = 5,
    cmove = 6,
    cmovne = 7,
    cmp = 8,
    dec = 9,
    div = 10,
    hlt = 11,
    imul = 12,
    inc = 13,
    ja = 14,
    jae = 15,
    jb = 16,
    jbe = 17,
    je = 18,
    jmp = 19,
    jne = 20,
    lea = 21,
    mov = 22,
    movs = 23,
    movsx = 24,
    movzx = 25,
    mul = 26,
    nop = 27,
    not_ = 28,
    or_ = 29,
    out = 30,
    pop = 31,
    push = 32,
    ret = 33,
    rol = 34,
    sbb = 35,
    seta = 36,
    setae = 37,
    setb = 38,
    setbe = 39,
    sete = 40,
    setne = 41,
    shl = 42,
    shr = 43,
    stos = 44,
    sub = 45,
    test_ = 46,
    ud2 = 47,
    xor_ = 48,
    adc = 49,
    cli = 50,
    cmova = 51,
    cmovb = 52,
    cmpxchg = 53,
    cpuid = 54,
    idiv = 55,
    int_ = 56,
    movdqu = 57,
    movups = 58,
    neg = 59,
    pshufd = 60,
    pushf = 61,
    rdmsr = 62,
    ror = 63,
    sar = 64,
    sti = 65,
    wrmsr = 66,
    xchg = 67,
    seto = 68,
    jl = 69,
    jge = 70,
    jle = 71,
    jg = 72,
    setl = 73,
    setge = 74,
    setle = 75,
    setg = 76,

    pub fn family(self: Operation) Family {
        return switch (self) {
            .mov => .move,
            .movsx, .movzx => .extend,
            .lea => .address,
            .movs, .stos => .string,
            .add, .adc, .cmp, .sbb, .sub => .arithmetic,
            .and_, .or_, .test_, .xor_ => .logic,
            .dec, .inc, .neg, .not_ => .unary,
            .rol, .ror, .sar, .shl, .shr => .shift,
            .imul, .mul => .multiply,
            .div, .idiv => .divide,
            .cmova,
            .cmovae,
            .cmovb,
            .cmove,
            .cmovne,
            .ja,
            .jae,
            .jb,
            .jbe,
            .je,
            .jne,
            .seta,
            .setae,
            .setb,
            .setbe,
            .sete,
            .setne,
            .seto,
            .jl,
            .jge,
            .jle,
            .jg,
            .setl,
            .setge,
            .setle,
            .setg,
            => .condition,
            .call, .jmp, .ret => .control,
            .pop, .push, .pushf => .stack,
            .bswap => .swap,
            .cmc => .carry,
            .nop => .nop,
            .hlt, .out, .ud2 => .boundary,
            .cli, .cpuid, .rdmsr, .sti, .wrmsr => .system,
            .movdqu, .movups, .pshufd => .vector,
            .cmpxchg, .xchg => .exchange,
            .int_ => .interrupt,
        };
    }
};

pub const implicit_registers_max: usize = 4;

pub const Instruction = struct {
    form: x86.Form,
    operation: Operation,
    family: Family,
    bytes: u4,
    register: ?x86.Register = null,
    register_access: x86.Access = .none,
    operand: x86.Operand = .none,
    operand_access: x86.Access = .none,
    embedded: ?x86.Register = null,
    embedded_access: x86.Access = .none,
    immediate: ?x86.Immediate = null,
    relative: ?i32 = null,
    modrm_mode: ?u2 = null,
    modrm_operand: ?u4 = null,
    implicit: [implicit_registers_max]x86.RegisterAccess = @splat(.{}),
    implicit_count: u3 = 0,

    pub fn implicitRegisters(self: *const Instruction) []const x86.RegisterAccess {
        std.debug.assert(self.implicit_count <= self.implicit.len);
        return self.implicit[0..self.implicit_count];
    }
};

comptime {
    std.debug.assert(@backingInt(Operation.xor_) == 48);
    std.debug.assert(implicit_registers_max <= std.math.maxInt(u3));
}
